import{_ as r,a0 as s,w as p,s as l,ao as u,I as o,x as a,a1 as n,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"在 Linux 上玩電子遊戲的三種方式 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上玩電子遊戲的三種方式 | LCTT (202206) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上玩電子遊戲的三種方式 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上玩電子遊戲的三種方式 | LCTT (202206) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202206/20210207 3 ways to play video games on Linux","title":"在 Linux 上玩電子遊戲的三種方式","tag":"202206","desc":""},"relativePath":"202206/20210207 3 ways to play video games on Linux.md","filePath":"[post].md"}'),d={name:"202206/20210207 3 ways to play video games on Linux.md"};function x(L,t,m,f,h,g){const e=s("Link");return p(),l("div",null,[t[15]||(t[15]=u('<h1 id="在-linux-上玩電子遊戲的三種方式" tabindex="-1">在 Linux 上玩電子遊戲的三種方式 <a class="header-anchor" href="#在-linux-上玩電子遊戲的三種方式" aria-label="Permalink to “在 Linux 上玩電子遊戲的三種方式”">​</a></h1><blockquote><p>如果你準備放下爆米花，想從各個角度體驗遊戲的話，那麼就在 Linux 下打開遊戲吧！</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202206/25/143306xijsi5aaz5jsj2aj.jpg" alt=""></p><p>如今，人們有更多喜歡 Linux 的理由。在這個系列裏，我將分享 21 個使用 Linux 的理由。今天，我將從遊戲開始。</p><p>我過去認為“遊戲玩家”是一種非常特殊的生物，要由科學家們在數年的研究和測試之後嚴謹地認定才行。我從來沒有把自己歸類為遊戲玩家，因為我所玩過的遊戲要麼是桌面遊戲（棋盤類遊戲和紙筆角色扮演遊戲），要麼是 NetHack、俄羅斯方塊。現在，在移動設備、遊戲機、電腦和電視機上都有遊戲，我覺得現在的承認有各種形式的遊戲玩家們了。如果你想自稱為遊戲玩家，你就可以是，不需任何資格認定。你不用必須在心裏熟記那些“上上下下左右左右BA”的科樂美秘籍（你甚至可以不知道這是什麼）；你也不用必須買過和玩過 3A 級遊戲。如果你時不時地玩遊戲，你就完全可以自稱為玩家。如果你想成為一名玩家，那麼現在使用 Linux 正當其時。</p><h3 id="歡迎來到遊戲世界" tabindex="-1">歡迎來到遊戲世界 <a class="header-anchor" href="#歡迎來到遊戲世界" aria-label="Permalink to “歡迎來到遊戲世界”">​</a></h3><p>剝除光鮮的廣告，在其下面，你肯定會發現一個欣欣向榮的遊戲世界。在人們相信不是電子表格也不是練習打字一類的軟件能掙錢以前，新興的遊戲市場已經開始發展起來了。<ruby>獨立遊戲<rt>indie game</rt></ruby>已經在流行文化上以各種方式打上了自己的烙印（或許你不相信，《我的世界》儘管不是開源的，但一開始就是一款獨立遊戲），這也證實了，在玩家眼裏，可玩性高於產品價值。</p><p>獨立開發者和開源開發者之間有很多交集。沒有什麼比帶着你的 Linux 筆記本電腦，瀏覽 itch.io 或你的發行版的軟件庫，尋找鮮為人知但珍貴的開源遊戲寶藏更有意義了。</p><p>有各種各樣的開源遊戲，包括大量的第一視角射擊遊戲、Nodulus 之類的益智遊戲、運輸大亨之類的策略經營遊戲、Jethook 之類的競速遊戲、Sauerbraten 之類的競速逃生遊戲，以及很多未提到的（多虧了像 Open Jam 這樣偉大的活動，每年都有新增的遊戲）。</p><p><img src="https://opensource.com/sites/default/files/game_0.png" alt="Jethook game screenshot"></p><p>總的來説，探索開源遊戲的世界的體驗，和購買大型遊戲工作室的產品帶來的即時滿足感有很大的不同。大型遊戲工作室生產的遊戲提供大量的視聽刺激、知名演員、和長達 60 小時以上的遊戲時長。而獨立和開源遊戲不能與之相提並論。但是話又説回來，大型遊戲工作室無法提供的是，當你發現一款別人未曾聽説過的遊戲時的產生的發現感和與個人相關的感受。當你意識到別人都非常想知道你剛玩過的哪個出色遊戲時，大型工作室也並不能提供這種緊迫感。（LCTT 校注：此處大概的意思是指大型工作室的作品已被人熟知，沒有什麼挖掘的新鮮感）</p><p>花點時間找出你最喜歡的遊戲，然後瀏覽下你的發行商的軟件倉庫、Flathub、開源的遊戲倉庫，看看你能發現什麼，如果發現你很喜歡的遊戲，就幫忙推廣一下吧。</p><h4 id="proton-和-wine" tabindex="-1">Proton 和 WINE <a class="header-anchor" href="#proton-和-wine" aria-label="Permalink to “Proton 和 WINE”">​</a></h4><p>Linux 上的遊戲並沒有止步於開源，但是從開源開始的。數年前 Valve 軟件公司通過發行 Linux 版的 Steam 客户端把 Linux 重新帶入遊戲市場時，人們希望這可以推動遊戲工作室能編寫原生的 Linux 遊戲。一些工作室這樣做了，但 Valve 公司並沒有成功的把 Linux 推為主要的平台，即使是 Valve 品牌的遊戲電腦。並且大多數遊戲工作室又轉回僅在 Windows 平台上開發遊戲的舊方式。</p><p>有趣的是，最終的結果是產生了更多的開源代碼。Valve 公司為 Linux 兼容創建了 Proton 工程，一個可以轉換 Windows 遊戲到 Linux 的兼容層。在 Proton 的內核層面，它使用了WINE（Wine Is Not an Emulator） —— 以開源的方式極好地重新實現了主要的 Windows 庫。</p><p>遊戲市場的成果，如今已經變成了開源世界的寶藏。今天，來自大型工作室的大多數遊戲都可以在 Linux 上像原生遊戲一樣運行。</p><p>當然，如果你是必須要在發行日就玩上最新版遊戲的這類玩家，你可能會遇到一些令人不愉快的“驚喜”。儘管那不是驚喜，很少有大型遊戲在發行時毫無漏洞，一週後才補上補丁。這些遊戲在 Proton 和 WINE 上運行時遇到這些錯誤可能更糟糕，因此 Linux 玩家通過避免儘早上車而避免這些問題。這種妥協可能是值得的。我玩過一些遊戲，它們在 Proton 平台運行完美，後來從憤怒的論壇帖子中發現，它在最新版的 Windows 上運行顯然充滿了致命的錯誤。總之，似乎來自大型工作室的遊戲並不完美，但你可能在 Linux 上遇到相似但不同的問題，正如你在 Windows 上遇到的。</p><h4 id="flatpak" tabindex="-1">Flatpak <a class="header-anchor" href="#flatpak" aria-label="Permalink to “Flatpak”">​</a></h4><p>Linux 近來歷史上最令人激動的發展就是 Flatpak 了，它是本地容器和打包的結合，它和遊戲無關（或者它和遊戲息息相關），它使得 Linux 應用基本上能被分發到任意的 Linux 發行版上。這也適用於遊戲，因為在遊戲中使用了相當多的前沿技術，而對發行版維護者來説，要跟上任何特定遊戲所需的所有最新版本可能是相當苛刻的。</p><p>Flapak 通過為應用程序庫抽象出一種通用的 Flatpak 特定的層，而將其從發行版中抽象出來。Flatpak 軟件包的發行者知道，如果一個庫不在 Flatpak SDK 中，那麼它必須要包含在 Flatpak 軟件包中，簡單而直接。</p><p>多虧了 Flatpak，Steam 客户端可以運行在像 Fedora 這樣的常用發行版上，也可以運行在 RHEL、Slackware 等從傳統角度看並不面向遊戲市場的操作系統上。</p><h4 id="lutris" tabindex="-1">Lutris <a class="header-anchor" href="#lutris" aria-label="Permalink to “Lutris”">​</a></h4><p>如果你並不急於在 Steam 上註冊賬號，那麼可以用我比較偏愛的遊戲客户端 Lutris 。表面上看，Lutris 是一個簡單的遊戲啓動器，當你想玩遊戲但還沒決定玩什麼的時候，你可以到這這裏找找。有了 Lutris，你可以將系統上的所有遊戲添加到你的遊戲庫，然後從 Lutris 界面啓動並立即玩起來。更好的是，Lutris 貢獻者（像我一樣）會定期發佈安裝腳本，使你可以輕鬆安裝自己的遊戲。這並不是必須的，但它可以是一個很好的捷徑，可以繞過一些繁瑣的配置。</p><p>Lutris 也可以藉助運行器或子系統，來運行那些不能從應用菜單直接啓動的遊戲。比如你想玩開源的《<ruby>魔獸塔防<rt>Warcraft Tower Defense</rt></ruby>》這樣的遊戲機遊戲，你必須運行模擬器。如果你已經安裝過模擬器的話，Lutris 可以幫你處理這一切。除此以外，如果你有一個 GOG.com 遊戲賬號，Lutris 可以訪問它，並可以把遊戲導入你的遊戲庫中。</p><p>沒有比這更容易的管理你的遊戲的方式了。</p><h3 id="去玩遊戲吧" tabindex="-1">去玩遊戲吧 <a class="header-anchor" href="#去玩遊戲吧" aria-label="Permalink to “去玩遊戲吧”">​</a></h3><p>Linux 遊戲是一種充實且給人力量的體驗。我過去避免玩電腦遊戲，因為我不覺得我有太多的選擇。似乎昂貴的遊戲總是在不斷髮布，並且不可避免的獲得好或者不好的極端體驗，然後很快又轉向下一個。另一方面，開源遊戲把我引入了遊戲的圈子。我見到過其他玩家和開發者。我見到過藝術家和音樂家、粉絲以及推廣者。我玩過各種各樣的我從來不知道的遊戲。其中一些甚至不夠我玩一下午，而其他的卻讓我長久的着迷於遊戲、修改、關卡設計和樂趣。</p><p>如果你準備好放下爆米花，從各個角度體驗下游戲的話，那就在 Linux 上開始遊戲吧。</p><hr>',29)),o("p",null,[t[1]||(t[1]=a("via: ",-1)),n(e,{href:"https://opensource.com/article/21/2/linux-gaming"},{default:i(()=>[...t[0]||(t[0]=[a("https://opensource.com/article/21/2/linux-gaming",-1)])]),_:1})]),o("p",null,[t[6]||(t[6]=a("作者：",-1)),n(e,{href:"https://opensource.com/users/seth"},{default:i(()=>[...t[2]||(t[2]=[a("Seth Kenlon",-1)])]),_:1}),t[7]||(t[7]=a(" 選題：",-1)),n(e,{href:"https://github.com/lujun9972"},{default:i(()=>[...t[3]||(t[3]=[a("lujun9972",-1)])]),_:1}),t[8]||(t[8]=a(" 譯者：",-1)),n(e,{href:"https://github.com/godgithubf"},{default:i(()=>[...t[4]||(t[4]=[a("godgithubf",-1)])]),_:1}),t[9]||(t[9]=a(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:i(()=>[...t[5]||(t[5]=[a("wxy",-1)])]),_:1})]),o("p",null,[t[12]||(t[12]=a("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[10]||(t[10]=[a("LCTT",-1)])]),_:1}),t[13]||(t[13]=a(" 原創編譯，",-1)),n(e,{href:"https://linux.cn/"},{default:i(()=>[...t[11]||(t[11]=[a("Linux中國",-1)])]),_:1}),t[14]||(t[14]=a(" 榮譽推出",-1))])])}const w=r(d,[["render",x]]);export{T as __pageData,w as default};
